61	#[derive(Clone)]
62	pub struct Item {
63	    item_type: ItemType,
64	    cursed: bool,
65	    enchantment: u32,
66	    material: String,
67	}
68	
69	impl Item {
70	    pub fn new(item_type: ItemType) -> Self {
71	        Self {
72	            item_type,
73	            cursed: false,
74	            enchantment: 0,
75	            material: String::new(),
76	        }
77	    }
78	
79	    /// The material the MHPCO recorded for this item.
80	    pub fn of_material(mut self, material: &str) -> Self {
81	        self.material = material.to_owned();
82	        self
83	    }
84	
85	    /// The item's enchantment level, as recorded by the MHPCO.
86	    pub fn with_enchantment(mut self, enchantment: u32) -> Self {
87	        self.enchantment = enchantment;
88	        self
89	    }
90	
91	    /// A cursed item carries the MHPCO's risk surcharge.
92	    pub fn cursed(mut self) -> Self {
93	        self.cursed = true;
94	        self
95	    }
96	
97	    /// The item-specific risk surcharges this item carries, charged against the
98	    /// item's own base premium rather than the policy total. A component carries
99	    /// none: the MHPCO records no curse, enchantment or material for one, so it
100	    /// is never an affected item.
101	    fn item_surcharge(&self) -> f64 {
102	        self.item_type
103	            .main_item_base_premium()
104	            .map_or(0.0, |item_base| item_base * self.risk_surcharge_rate())
105	    }
106	
107	    /// Highly enchanted for rating purposes. The MHPCO reads a separate, higher
108	    /// enchantment threshold when reimbursing damage, so this one is named for
109	    /// the premium it surcharges.
110	    fn is_highly_enchanted(&self) -> bool {
111	        self.enchantment >= HIGH_ENCHANTMENT_LEVEL
112	    }
113	
114	    /// The share of a damage amount the MHPCO reimburses for this item, under the
115	    /// reimbursement clauses it reads today. Only one clause reduces the share:
116	    /// damage to a very highly enchanted item is reimbursed at half. That
117	    /// enchantment threshold is a higher one than the threshold that surcharges
118	    /// the premium, and the MHPCO reads the two independently -- the level and the
119	    /// share, though, are the one clause, so they are read together here.
120	    ///
121	    /// The MHPCO's other reimbursement clause -- dragon material is reimbursed in
122	    /// full -- deliberately has no branch here. Full reimbursement is already what
123	    /// an item under no clause receives, and the half-reimbursement clause wins
124	    /// wherever both apply, so the dragon clause cannot move any share the MHPCO
125	    /// recognises. The material stays a recorded property of the item; give it a
126	    /// branch only when a clause makes it change a share.
127	    fn reimbursement_share(&self) -> f64 {
128	        if self.enchantment >= HALF_REIMBURSEMENT_LEVEL {
129	            HALF_REIMBURSEMENT
130	        } else {
131	            FULL_REIMBURSEMENT
132	        }
133	    }
134	
135	    /// Curse and high enchantment are independent risks; an item carrying both
136	    /// is surcharged for both.
137	    fn risk_surcharge_rate(&self) -> f64 {
138	        let curse = if self.cursed { CURSE_SURCHARGE } else { 0.0 };
139	        let enchantment = if self.is_highly_enchanted() {
140	            HIGH_ENCHANTMENT_SURCHARGE
141	        } else {
142	            0.0
143	        };
144	        curse + enchantment
145	    }
146	}
147	
148	const PROCESSING_FEE: u64 = 5;
149	const FIRST_INSURANCE_SURCHARGE: f64 = 0.10;
150	/// Cursed items add a risk surcharge on their own base premium.
151	const CURSE_SURCHARGE: f64 = 0.50;
152	/// Long-standing customers -- 2 or more years of business with the MHPCO --
153	/// receive a loyalty discount on the policy base premium.
154	const LOYALTY_YEARS: u32 = 2;
155	const LOYALTY_DISCOUNT: f64 = 0.20;
156	/// Customers receive a discount on each contract after their first.
157	const FOLLOW_UP_CONTRACT_DISCOUNT: f64 = 0.15;
158	/// Highly enchanted items -- enchantment level 5 or above -- add a risk
159	/// surcharge on their own base premium.
160	const HIGH_ENCHANTMENT_LEVEL: u32 = 5;
161	const HIGH_ENCHANTMENT_SURCHARGE: f64 = 0.30;
162	/// Components -- for example runes and moonstones -- share one price-list row.
163	const COMPONENT_BASE_PREMIUM: f64 = 25.0;
164	
165	/// How the MHPCO settles a rated premium into the amount it bills: the rated
166	/// fraction is rounded in the MHPCO's own favour -- upwards, the larger amount
167	/// -- and the processing fee is added to every premium at the very end.
168	fn settled_premium(rated: f64) -> u64 {
169	    rated.ceil() as u64 + PROCESSING_FEE
170	}
171	
172	/// The policy-wide modifier rate, charged against the policy base premium --
173	/// the sum of all item base premiums. The MHPCO nets its policy-wide modifiers
174	/// against one another: a first insurance carries an initial assessment
175	/// surcharge, a long-standing customer earns a loyalty discount, and every
176	/// contract after the customer's first earns a follow-up discount.
177	fn policy_modifier_rate(customer: &Customer, contract: Contract) -> f64 {
178	    let loyalty = if customer.is_long_standing() {
179	        LOYALTY_DISCOUNT
180	    } else {
181	        0.0
182	    };
183	    let follow_up = match contract {
184	        Contract::First => 0.0,
185	        Contract::FollowUp => FOLLOW_UP_CONTRACT_DISCOUNT,
186	    };
187	    FIRST_INSURANCE_SURCHARGE - loyalty - follow_up
188	}
189	
190	/// A building block of exactly 3 alike components is offered at this price
191	/// instead of the per-component base premium.
192	const COMPONENT_BLOCK_SIZE: usize = 3;
193	const COMPONENT_BLOCK_BASE_PREMIUM: f64 = 60.0;
194	
195	fn component_charge(alike_count: usize) -> f64 {
196	    if alike_count == COMPONENT_BLOCK_SIZE {
197	        COMPONENT_BLOCK_BASE_PREMIUM
198	    } else {
199	        alike_count as f64 * COMPONENT_BASE_PREMIUM
200	    }
201	}
202	
203	/// The policy's components gathered into groups of alike ones, each group
204	/// reported as its size. Alike components are the ones charged together, so the
205	/// MHPCO's reading of "alike" -- same item type -- lives here and nowhere else.
206	fn alike_component_groups(items: &[Item]) -> Vec<usize> {
207	    let mut groups: Vec<(ItemType, usize)> = Vec::new();
208	    for component in items.iter().filter(|item| item.item_type.is_component()) {
209	        match groups
210	            .iter_mut()
211	            .find(|(group_type, _)| *group_type == component.item_type)
212	        {
213	            Some((_, count)) => *count += 1,
214	            None => groups.push((component.item_type, 1)),
215	        }
216	    }
217	    groups.into_iter().map(|(_, count)| count).collect()
218	}
219	
220	/// Main items are charged one price-list row each, individually.
221	fn main_items_base_premium(items: &[Item]) -> f64 {
222	    items
223	        .iter()
224	        .filter_map(|item| item.item_type.main_item_base_premium())
225	        .sum()
226	}
227	
228	/// Components are charged per group of alike components, so that a group of
229	/// exactly 3 earns the block price.
230	fn component_blocks_base_premium(items: &[Item]) -> f64 {
231	    alike_component_groups(items)
232	        .into_iter()
233	        .map(component_charge)
234	        .sum()
235	}
236	
237	/// The policy base premium is the sum of the items' base premiums, with alike
238	/// components charged as blocks.
239	pub fn policy_base_premium(items: &[Item]) -> f64 {
240	    main_items_base_premium(items) + component_blocks_base_premium(items)
241	}
242	
243	/// Item-specific modifiers apply to the base premium of the affected item, not
244	/// to the policy total.
245	fn item_surcharges(items: &[Item]) -> f64 {
246	    items.iter().map(Item::item_surcharge).sum()
247	}
248	
249	/// A customer's first contract with the MHPCO, or any contract after it.
250	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
251	pub enum Contract {
252	    First,
253	    FollowUp,
254	}
255	
256	/// What the MHPCO rates this policy at, as an exact fraction: the policy base
257	/// premium, modified policy-wide for the customer and the contract, plus the
258	/// surcharges carried by the individual affected items. This is the rating
259	/// decision; it is deliberately unrounded and carries no processing fee.
260	fn rated_premium(customer: &Customer, items: &[Item], contract: Contract) -> f64 {
261	    let policy_base = policy_base_premium(items);
262	    policy_base + policy_base * policy_modifier_rate(customer, contract) + item_surcharges(items)
263	}
264	
265	/// The premium the customer is billed: the MHPCO rates the policy, then settles
266	/// the rated amount into the amount billed.
267	pub fn quote(customer: &Customer, items: &[Item], contract: Contract) -> u64 {
268	    settled_premium(rated_premium(customer, items, contract))
269	}
270	
271	/// Damage to an item enchanted at this level or above is reimbursed at half.
272	const HALF_REIMBURSEMENT_LEVEL: u32 = 8;
273	const HALF_REIMBURSEMENT: f64 = 0.50;
274	const FULL_REIMBURSEMENT: f64 = 1.0;
275	
276	/// A deductible applies per damage event, once for each damaged item.
277	const DEDUCTIBLE_PER_DAMAGE: f64 = 100.0;
278	
279	/// A single damaged item reported in an incident.
280	pub struct Damage {
281	    item_type: ItemType,
282	    amount: i64,
283	}
284	
285	impl Damage {
286	    pub fn new(item_type: ItemType, amount: i64) -> Self {
287	        Self { item_type, amount }
288	    }
289	
290	    /// What the MHPCO reimburses for this one damaged item, as an exact
291	    /// fraction: the share of the damage amount the insured item's clauses
292	    /// allow, less the deductible that applies once per damage event.
293	    fn reimbursement(&self, insured: &Item) -> f64 {
294	        self.amount as f64 * insured.reimbursement_share() - DEDUCTIBLE_PER_DAMAGE
295	    }
296	}
297	
298	/// How the MHPCO settles a reimbursed amount into the amount it pays out: the
299	/// reimbursed fraction is rounded in the MHPCO's own favour -- downwards, the
300	/// smaller amount -- which is the opposite direction from a premium.
301	fn settled_payout(reimbursed: f64) -> u64 {
302	    reimbursed.floor() as u64
303	}
304	
305	/// What the MHPCO pays out on one claim.
306	#[derive(Debug, PartialEq, Eq)]
307	pub struct Settlement {
308	    pub payout: u64,
309	}
310	
311	/// A policy the MHPCO has written over a customer's items.
312	pub struct Policy {
313	    items: Vec<Item>,
314	}
315	
316	impl Policy {
317	    pub fn new(items: &[Item]) -> Self {
318	        Self {
319	            items: items.to_vec(),
320	        }
321	    }
322	
323	    /// The insured item a reported damage refers to. Which of the policy's items
324	    /// answers for a damage is the MHPCO's coverage question, kept apart from how
325	    /// the damage is reimbursed: an incident reporting more damaged items of a
326	    /// type than the policy insures, or an item the policy never covered, is a
327	    /// coverage failure and not yet active behaviour.
328	    fn insured_item_for(&self, damage: &Damage) -> &Item {
329	        self.items
330	            .iter()
331	            .find(|item| item.item_type == damage.item_type)
332	            .expect("the damaged item is covered by this policy")
333	    }
334	
335	    /// The MHPCO settles an incident against this policy: it reimburses each
336	    /// damaged item under the clauses of the insured item that answers for it,
337	    /// then settles the total into the amount it pays out.
338	    pub fn claim(&mut self, damages: &[Damage]) -> Result<Settlement, String> {
339	        let reimbursed: f64 = damages
340	            .iter()
341	            .map(|damage| damage.reimbursement(self.insured_item_for(damage)))
342	            .sum();
343	        Ok(Settlement {
344	            payout: settled_payout(reimbursed),
345	        })
346	    }
347	}
